import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
import { handlePrivateFileRequest, notFound } from "./handler.ts";
// Generated by `node scripts/build-private-files.mjs` from ./files/ (gitignored).
import { PRIVATE_FILES } from "./files.generated.ts";

async function getUserId(jwt: string): Promise<string | null> {
  const url = Deno.env.get("SUPABASE_URL");
  const anonKey =
    Deno.env.get("SUPABASE_ANON_KEY") ??
    Deno.env.get("SUPABASE_PUBLISHABLE_KEY");
  if (!url || !anonKey) return null;
  const client = createClient(url, anonKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await client.auth.getUser(jwt);
  if (error || !data.user) return null;
  return data.user.id;
}

// No logging in this function: never echo headers or session tokens.
Deno.serve(async (req: Request) => {
  try {
    return await handlePrivateFileRequest(req, {
      ownerId: Deno.env.get("PRIVATE_FILES_OWNER_ID"),
      files: PRIVATE_FILES,
      getUserId,
      allowedOriginsEnv: Deno.env.get("CORS_ALLOWED_ORIGINS"),
    });
  } catch {
    return notFound();
  }
});
